170	/// Execute one combat damage step.
171	/// If `first_strike_only`, only creatures with first/double strike deal damage.
172	/// If not, creatures without first strike deal damage (plus double strikers again).
173	fn deal_damage_step(
174	    state: &mut GameState,
175	    combat: &CombatState,
176	    registry: &CardRegistry,
177	    first_strike_only: bool,
178	) {
179	    for (&attacker_id, &defending_player) in &combat.attackers {
180	        if state.get_object(attacker_id).map(|o| o.zone != Zone::Battlefield).unwrap_or(true) {
181	            continue;
182	        }
183	
184	        let has_fs = state.has_keyword(attacker_id, Keyword::FirstStrike, registry);
185	        let has_ds = state.has_keyword(attacker_id, Keyword::DoubleStrike, registry);
186	        let attacker_deals = if first_strike_only {
187	            has_fs || has_ds
188	        } else {
189	            !has_fs || has_ds // normal strikers + double strikers
190	        };
191	
192	        let attacker_power = if attacker_deals {
193	            state.effective_power(attacker_id, registry).unwrap_or(0).max(0) as u32
194	        } else {
195	            0
196	        };
197	
198	        let has_trample = state.has_keyword(attacker_id, Keyword::Trample, registry);
199	        let has_deathtouch_attacker = state.has_keyword(attacker_id, Keyword::Deathtouch, registry);
200	
201	        let blockers = combat.blocker_assignments.get(&attacker_id)
202	            .cloned()
203	            .unwrap_or_default();
204	
205	        if blockers.is_empty() {
206	            // Unblocked: deal damage to defending player.
207	            if attacker_power > 0 {
208	                deal_damage_to_player(state, attacker_id, defending_player, attacker_power, registry);
209	            }
210	        } else {
211	            // Blocked: distribute damage to blockers, with trample overflow.
212	            let mut remaining_power = attacker_power;
213	
214	            for &blocker_id in &blockers {
215	                if state.get_object(blocker_id).map(|o| o.zone != Zone::Battlefield).unwrap_or(true) {
216	                    continue;
217	                }
218	
219	                // Blocker deals damage to attacker.
220	                let blocker_has_fs = state.has_keyword(blocker_id, Keyword::FirstStrike, registry);
221	                let blocker_has_ds = state.has_keyword(blocker_id, Keyword::DoubleStrike, registry);
222	                let blocker_deals = if first_strike_only {
223	                    blocker_has_fs || blocker_has_ds
224	                } else {
225	                    !blocker_has_fs || blocker_has_ds
226	                };
227	
228	                if blocker_deals {
229	                    let blocker_power = state.effective_power(blocker_id, registry).unwrap_or(0).max(0) as u32;
230	                    if blocker_power > 0 {
231	                        deal_damage_to_creature(state, blocker_id, attacker_id, blocker_power, registry);
232	                    }
233	                }
234	
235	                // Attacker deals damage to blocker.
236	                if remaining_power > 0 {
237	                    let blocker_toughness = state.effective_toughness(blocker_id, registry).unwrap_or(0);
238	                    let blocker_damage = state.get_object(blocker_id).map(|o| o.damage_marked).unwrap_or(0);
239	                    let lethal = if has_deathtouch_attacker {
240	                        1 // deathtouch: 1 damage is lethal
241	                    } else {
242	                        (blocker_toughness - blocker_damage as i32).max(0) as u32
243	                    };
244	
245	                    let assigned = if has_trample {
246	                        remaining_power.min(lethal) // assign minimum lethal, save rest for trample
247	                    } else {
248	                        remaining_power // assign all to this blocker
249	                    };
250	
251	                    if assigned > 0 {
252	                        deal_damage_to_creature(state, attacker_id, blocker_id, assigned, registry);
253	                        remaining_power -= assigned;
254	                    }
255	                }
256	            }
257	
258	            // Trample: remaining damage goes to the defending player.
259	            if has_trample && remaining_power > 0 {
260	                deal_damage_to_player(state, attacker_id, defending_player, remaining_power, registry);
261	            }
262	        }
263	    }
264	}
