615	/// Check if a blocker can legally block a specific attacker.
616	/// Enforces flying (only blocked by flying/reach) and intimidate (only by artifact/same color).
617	pub fn can_block_attacker(state: &GameState, blocker_id: ObjectId, attacker_id: ObjectId, registry: &CardRegistry) -> bool {
618	    // Flying: can only be blocked by creatures with flying or reach.
619	    if state.has_keyword(attacker_id, Keyword::Flying, registry) {
620	        if !state.has_keyword(blocker_id, Keyword::Flying, registry)
621	            && !state.has_keyword(blocker_id, Keyword::Reach, registry) {
622	            return false;
623	        }
624	    }
625	
626	    // Intimidate: can only be blocked by artifact creatures or creatures that share a color.
627	    if state.has_keyword(attacker_id, Keyword::Intimidate, registry) {
628	        let blocker = match state.get_object(blocker_id) {
629	            Some(o) => o,
630	            None => return false,
631	        };
632	        let is_artifact = registry.card_data(blocker.card_id)
633	            .map(|d| d.card_types.contains(&crate::types::CardType::Artifact))
634	            .unwrap_or(false);
635	        if !is_artifact {
636	            let attacker = match state.get_object(attacker_id) {
637	                Some(o) => o,
638	                None => return false,
639	            };
640	            let shares_color = attacker.colors.iter().any(|c| blocker.colors.contains(c));
641	            if !shares_color {
642	                return false;
643	            }
644	        }
645	    }
646	
647	    // Menace: must be blocked by two or more creatures (handled at validation, not per-blocker).
648	
649	    // Block restriction (e.g., Orchard Spirit: only flying/reach can block).
650	    for source in state.objects.values() {
651	        if source.zone != crate::types::Zone::Battlefield {
652	            continue;
653	        }
654	        // Check instance-level effects first (e.g., equipment with BlockRestriction).
655	        if let Some(ref instance_effects) = source.instance_continuous_effects {
656	            for effect in instance_effects {
657	                if let crate::types::ContinuousEffect::BlockRestriction { allowed_blockers, scope } = effect {
658	                    if state.effect_applies_to(attacker_id, scope, source.id, source.controller, registry) {
659	                        if !state.matches_filter(blocker_id, allowed_blockers, source.controller, registry) {
660	                            return false;
661	                        }
662	                    }
663	                }
664	            }
665	        } else if let Some(behavior) = registry.get(source.card_id) {
